    function notify(message,correct=null,sfxKind=''){feedback=message;const node=q('#gp-feedback');if(node){node.innerHTML=message;node.dataset.kind=correct===null?'neutral':correct?'good':'bad'}if(sfxKind)sfx(sfxKind);else if(correct===true)sfx('correct');else if(correct===false)sfx('wrong')}
