    function stats(){const endless=level===2||practiceMode;return `<div class="gp-hud"><div class="gp-stat gp-score"><small>${endless?'累计得分':T('play.score')}</small><strong id="gp-score">0</strong></div>${['runner','match'].includes(gameId)?(endless?`<div class="gp-stat gp-goal"><small>挑战时长</small><strong id="gp-elapsed">0<em>s</em></strong></div><div class="gp-stat gp-goal"><small>最高得分</small><strong id="gp-peak">0</strong></div>`:`<div class="gp-stat"><small>${T('play.time')}</small><strong id="gp-clock">${Math.ceil(s.duration)}<em>s</em></strong></div><div class="gp-stat gp-goal"><small>${levelLabel(level)}</small><strong>${s.goal}<em>目标分</em></strong></div>`):gameId==='sorter'?`<div class="gp-stat"><small>${T('play.sortDone',{done:0})}</small><strong id="gp-sort-count">01 <em>/ 12</em></strong></div><div class="gp-stat gp-streak"><small>连击</small><strong id="gp-sort-streak">0</strong></div><div class="gp-stat gp-goal"><small>${T('play.targetLabel')}</small><strong>60<em>分</em></strong></div><div class="gp-goal-track" id="gp-sort-track"><div class="gp-goal-fill" id="gp-sort-fill"></div><span id="gp-sort-track-label">0 / 12</span></div>`:`<div class="gp-stat"><small>${T('play.turnTeam')}</small><strong id="gp-turn-name"></strong></div><div class="gp-stat"><small>${T('play.rankLabel')}</small><strong>100<em>/ 75 / 50 / 25</em></strong></div>`}</div>`}
    function begin(){const appEl0=host.querySelector('.gp-app');if(appEl0)appEl0.classList.remove('gp-settled');sfx('tap');phase='active';paused=false;age=0;last=0;lockUntil=0;afterLock=null;quizStartedAt=0;quizResponse=null;feedback='';selected=-1;hintPair=[];settled=false;result=null;lastTimerCue=null;hintCards=2;diceVisual=0;diceSpinning=false;nextDiceFaceAt=0;runId=root.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2);if(gameId==='sorter')s=G.createSort();else if(gameId==='ludo'){s=G.makeBoard(G.createLudo({...options,names:options.names.slice(0,options.humans)}));cpuAt=.8}else s=gameId==='runner'?G.createRunner(practiceMode?2:level):G.createMatch(practiceMode?2:level);shell(`<main class="gp-play">${stats()}<div id="gp-stage"></div><p class="gp-inline-rule">${rule()}</p></main>`,['runner','match'].includes(gameId)?levelLabel(level):T('play.stageSub'));renderStage();if(gameId==='runner')drawRunner();if(document.hidden)pause(true)}
