    function keyboard(event){if(!alive||!host.contains(event.target)||event.target.closest('select,input,textarea'))return;if(event.key==='Escape'){event.preventDefault();pause();return}if(phase!=='active'||paused)return;if(gameId==='sorter'&&/^[1-4]$/.test(event.key)){event.preventDefault();answerSort(D.categories[Number(event.key)-1].id)}if(gameId==='runner'&&!event.repeat){if(event.key==='ArrowUp'||event.key==='ArrowDown'){event.preventDefault();let lane;if(event.key==='ArrowUp')lane=(s.lane+2)%3;else lane=(s.lane+1)%3;G.moveRunner(s,lane);sfx('move');drawRunner();qa('[data-gact=lane]').forEach(b=>b.classList.toggle('is-active',Number(b.dataset.lane)===s.lane));if(tutorialActive&&!tutSteps?.[tutStep]?.spawn){tutDone=true}}}if(gameId==='match'&&event.key.startsWith('Arrow')){const tile=event.target.closest('[data-index]');if(!tile)return;const i=Number(tile.dataset.index),next=i+({ArrowUp:-6,ArrowDown:6,ArrowLeft:-1,ArrowRight:1}[event.key]||0);if(next>=0&&next<36&&G.adjacent(i,next)){event.preventDefault();q(`[data-index="${next}"]`)?.focus()}}if(tutDone){tutDone=false;tutorialAdvance&&tutorialAdvance()}}
